const $ = s=>document.querySelector(s);
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={image:'M3 4h20v18H3zM3 17l6-6 5 5 3-3 6 6M18 7h.01',file:'M5 2h10l6 6v16H5zM15 2v7h6M9 14h8M9 18h8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',library:'M4 4h5v16H4zM11 4h4v16h-4zM17 5l4-1 3 15-4 1z',pen:'m15 5 4 4M4 20l4-1L21 6a2.8 2.8 0 0 0-4-4L4 15z',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 11h16M8 15h2M14 15h2',box:'m3 7 9-4 9 4v11l-9 4-9-4zM3 7l9 5 9-5M12 12v10',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plus:'M12 4v16M4 12h16',arrow:'M4 12h16M14 6l6 6-6 6',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',check:'m5 12 4 4L20 5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2'};
const icon=(name)=>`<svg viewBox="0 0 26 26" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const btn=(label,action,kind='',data='')=>`<button class="btn ${kind}" data-action="${action}" ${data}>${label}</button>`;
const labels={overview:'运营总览',library:'灵感收藏',studio:'创作工作台',calendar:'发布排期',accounts:'账号管理',product:'产品资料',settings:'设置与接入'};
const statusNames={draft:'草稿',scheduled:'已排期',blocked:'待接通 / 待处理',uncertain:'待核对',publishing:'发布中',published:'已核对发布',cancelled:'已取消',failed:'失败',needs_source:'待补截图',ready:'待分析',analyzed:'已分析',saved:'已收藏'};
const badge=(status)=>`<span class="badge ${['blocked','uncertain','needs_source'].includes(status)?'warn':['draft','saved','ready','cancelled'].includes(status)?'neutral':''}">${esc(statusNames[status]||status)}</span>`;
const date=(d)=>new Date(d).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
let S, page=location.hash.slice(1)||'overview', selected=null, edit=null, dirty=false, slide=0, filter='all', query='', busy=false, toastTimer, accountFilter='all', accountView='active', productTab='facts', assetFilter='all';
async function api(url,body,method='POST'){const r=await fetch('/api/'+url,{method,headers:{'Content-Type':'application/json'},...(body!==undefined?{body:JSON.stringify(body)}:{})});let value;try{value=await r.json();}catch{throw Error('服务暂时不可用，请检查本地服务');}if(!r.ok)throw Error(value.error||'操作失败');return value;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
async function refresh(renderPage=true){S=await api('state',undefined,'GET');if(accountFilter!=='all'&&!allAccounts().some(a=>a.id===accountFilter))accountFilter='all';if(renderPage)render();}
function allAccounts(){return S.accounts||[];}
function activeAccounts(){return allAccounts().filter(a=>!a.archived);}
function accountById(id){return allAccounts().find(a=>a.id===id);}
function accountName(id){return accountById(id)?.name||'未分配账号';}
function chosenAccount(){return accountById(accountFilter)||accountById(S.defaultAccountId)||activeAccounts()[0];}
function accountReady(id){return Boolean(S.capabilities.accounts?.[id]?.publisher);}
function scoped(items){return accountFilter==='all'?items:items.filter(x=>x.accountId===accountFilter);}
function accountOptions(value,{all=false,archived=false}={}){return `${all?'<option value="all">全部账号</option>':''}${allAccounts().filter(a=>archived||!a.archived||a.id===value).map(a=>`<option value="${esc(a.id)}"${a.id===value?' selected':''}>${esc(a.name)}${a.archived?' · 已归档':!a.enabled?' · 已停用':''}${a.id===S.defaultAccountId?' · 默认':''}</option>`).join('')}`;}
function accountSelect(name,value,label='所属账号'){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="accountId">${accountOptions(value)}</select></div>`;}
function accountTag(id,snapshot=''){return `<span class="account-tag">${esc(accountById(id)?.name||snapshot||'未分配账号')}</span>`;}
function draftCurrent(){const items=scoped(S.drafts);return items.find(d=>d.id===selected)||items[0];}
function nav(to){if(dirty&&!confirm('草稿有未保存的修改，确定离开吗？'))return;dirty=false;edit=null;slide=0;page=labels[to]?to:'overview';location.hash=page;render();window.scrollTo(0,0);}
function field(label,name,value,type='text',hint=''){return `<div class="field"><label for="${name}">${label}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" rows="5">${esc(value)}</textarea>`:`<input id="${name}" name="${name}" type="${type}" value="${esc(value)}">`}${hint?`<small>${hint}</small>`:''}</div>`;}
function wrap(text,max){const result=[];for(const raw of String(text).split('\n')){let line='',units=0;for(const c of raw){const size=/[\x00-\x7f]/.test(c)?.57:1;if(units+size>max&&line){result.push(line);line='';units=0;}line+=c;units+=size;}result.push(line);}return result;}
function coverSVG(d,index=0){const p=d.slides?.[index]||{headline:d.title,body:''};const titleLines=wrap(p.headline,index?14:9);const fs=titleLines.length>5?65:index?74:103;const th=titleLines.length*fs*1.22;const bodyLines=wrap(p.body||'',22);const bodyY=Math.max(610,305+th);const bfs=Math.min(35,Math.max(17,(1330-bodyY)/Math.max(1,bodyLines.length)/1.55));
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1600" viewBox="0 0 1200 1600"><rect width="1200" height="1600" fill="#ffffff"/><g stroke="#edf3fc" stroke-width="1"><path d="M0 1200H1200M0 1050H1200M0 900H1200M0 750H1200M0 600H1200M0 450H1200M300 200V1400M600 200V1400M900 200V1400"/></g><rect x="84" y="91" width="11" height="29" rx="5" fill="#007aff"/><text x="117" y="116" font-family="sans-serif" font-size="25" fill="#007aff">${esc(d.series||'通信小麻烦')}</text><text x="1098" y="117" text-anchor="end" font-family="monospace" font-size="23" fill="#9aafc9">HUMAN PATCH / ${String(index+1).padStart(2,'0')}</text><g fill="#1d1d1f" font-family="PingFang SC,Microsoft YaHei,sans-serif" font-weight="600" font-size="${fs}">${titleLines.map((line,i)=>`<text x="84" y="${320+i*fs*1.22}"${i===titleLines.length-1?' fill="#007aff"':''}>${esc(line)}</text>`).join('')}</g><g fill="#8199b8" font-family="PingFang SC,Microsoft YaHei,sans-serif" font-size="${bfs}">${bodyLines.map((line,i)=>`<text x="88" y="${bodyY+i*bfs*1.55}">${esc(line)}</text>`).join('')}</g><circle cx="1050" cy="1290" r="74" fill="none" stroke="#d4e5fc" stroke-width="2"/><path d="M1018 1290h62m-27-27 27 27-27 27" fill="none" stroke="#007aff" stroke-width="4"/><path d="M84 1430H1116" stroke="#e1eaf6"/><text x="84" y="1500" fill="#1d1d1f" font-family="sans-serif" font-size="31">${esc(S.product.brand)} · ${esc(S.product.name)}</text><text x="1116" y="1500" text-anchor="end" fill="#9aafc9" font-family="sans-serif" font-size="21">原创文字图解 · 开发内测</text></svg>`;
}
const coverURI=(d,i=0)=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(coverSVG(d,i));
function topHead(title,action=''){return `<header class="page-head"><h1>${title}</h1><div class="actions">${['overview','studio','calendar'].includes(page)?`<select id="account-filter" class="account-filter" aria-label="筛选账号">${accountOptions(accountFilter,{all:true,archived:true})}</select>`:''}${action}</div></header>`;}
function connectors(){const account=chosenAccount(),ready=account&&accountReady(account.id);return `<div class="connect-row"><div><div class="connect-title">${icon('spark')}AI 创作模型</div><p>${S.capabilities.ai?esc(S.capabilities.model):'未配置'}</p></div><span class="badge ${S.capabilities.ai?'':'neutral'}">${S.capabilities.ai?'已配置':'待配置'}</span></div><div class="connect-row"><div><div class="connect-title">${icon('link')}小红书发布器</div><p>${account?esc(account.name)+' · '+(ready?'目标已配置，待实际核对':'未配置发布目标'):'请先添加账号'}</p></div><span class="badge ${ready?'':'neutral'}">${ready?'已配置':'未接通'}</span></div><div class="connect-row"><div><div class="connect-title">${icon('box')}飞书产品资料</div><p>手动资料</p></div><span class="badge neutral">未同步</span></div>`;}

function overview(){const drafts=scoped(S.drafts),jobs=scoped(S.jobs),account=chosenAccount(),dailySettings=account?.settings||S.settings;const pending=drafts.filter(d=>d.status==='draft').length;const scheduled=jobs.filter(j=>j.status==='scheduled').length;const published=jobs.filter(j=>j.status==='published').length;
return topHead('运营总览',`<div class="actions">${btn(icon('plus')+' 收藏灵感','upload','light')}${btn('新建草稿','generate')}</div>`)+`<section class="stats">${[['灵感收藏',S.inspirations.length,'份','把喜欢的内容留在这里'],['待打磨草稿',pending,'篇','有想法，也有产品依据'],['等待发布',scheduled,'篇',S.settings.enabled?'每日任务已开启':'每日任务尚未开启'],['实际已发布',published,'篇',published?'已取得核对后的笔记链接':'还没有真实发布记录']].map(([l,n,u,f],i)=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-value">${n}<span>${u}</span></div></div>`).join('')}</section><div class="dashboard-columns"><section><div class="section-head"><h2>最近草稿</h2>${btn('全部草稿','nav','ghost','data-page="studio"')}</div><div class="draft-list">${drafts.slice(0,3).map(d=>`<article class="draft-row"><img class="draft-thumb" src="${coverURI(d)}" alt="${esc(d.title)}封面"><div class="draft-row-info"><h3>${esc(d.title)}</h3><div class="draft-meta">${badge(d.status)}${accountTag(d.accountId)}<span>${esc(d.series)} · ${d.slides.length} 页</span></div></div>${btn('编辑','edit','light',`data-id="${d.id}"`)}</article>`).join('')||`<div class="empty">暂无草稿${btn('新建草稿','generate')}</div>`}</div><div class="section-head"><h2>最近收藏</h2>${btn('全部收藏','nav','ghost','data-page="library"')}</div>${S.inspirations.slice(0,2).map(r=>`<div class="draft-row"><div class="avatar">↗</div><div class="draft-row-info"><h3>${esc(r.title)}</h3><div class="draft-meta">${esc(r.tags.slice(0,3).join(' / '))}</div></div>${btn('查看','reference','ghost',`data-id="${r.id}"`)}</div>`).join('')}</section><aside><div class="section-head"><h2>接入状态</h2></div><div class="panel">${connectors()}<div class="note-box">现在可以收藏、编辑、导出与排期。实际分析和发布需接通对应服务。</div>${btn('管理接入 →','nav','ghost','data-page="settings"')}</div><div class="section-head"><h2>每日任务</h2></div><div class="panel"><h3>${account?esc(account.name):'暂无账号'}</h3><p class="preview-caption">${dailySettings?.enabled?'已启用':'未启用'} · ${esc(dailySettings?.time||'10:00')}<br>${esc(dailySettings?.timezone||'Asia/Shanghai')} · ${dailySettings?.mode==='review'?'审核后发布':'自动生成并发布'}</p>${account&&!account.archived?btn('设置','daily','ghost',`data-id="${account.id}"`):''}</div></aside></div>`;}
function library(){let items=S.inspirations.filter(r=>(filter==='all'||(filter==='pool'?r.pool:r.status===filter))&&[r.title,...r.tags,r.note].join(' ').toLowerCase().includes(query.toLowerCase()));
return topHead('灵感收藏',btn(icon('plus')+' 收藏灵感','upload'))+`<div class="filters">${[['all','全部收藏'],['analyzed','已分析'],['ready','待分析'],['pool','每日选题池']].map(([key,label])=>`<button class="filter ${filter===key?'active':''}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}<label class="search"><input id="library-search" type="search" aria-label="搜索收藏" placeholder="搜索标题、标签、备注…" value="${esc(query)}"></label></div><div class="library-grid">${items.map((r,i)=>`<article class="ref-card"><button class="ref-cover" data-action="reference" data-id="${r.id}" aria-label="查看 ${esc(r.title)}">${r.assets[0]?`<img src="${esc(r.assets[0])}" alt="收藏的参考截图"><span class="cover-shade"></span><span class="cover-label">REFERENCE / ${String(i+1).padStart(2,'0')}</span>`:`<div class="text-cover"><div class="mono">SAVED REFERENCE / ${String(i+1).padStart(2,'0')}</div><h3>${esc(r.title)}</h3><div class="big-arrow">↗</div></div>`}</button><div class="ref-info"><h3>${esc(r.title)}</h3><div class="tags">${r.tags.slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')||'<span class="tag">未分类</span>'}</div><div class="ref-footer">${badge(r.status)}${btn('参考创作','generate','ghost',`data-id="${r.id}"`)}</div></div></article>`).join('')}<button class="upload-card" data-action="upload"><span class="plus">+</span><strong>添加收藏</strong><p>上传一组截图，或保存一个链接<br>相同笔记与截图会自动合并</p></button></div>${!items.length&&S.inspirations.length?'<p class="preview-caption">没有匹配的收藏，试试其他关键词。</p>':''}`;}
function studio(){const d=draftCurrent();if(!d)return topHead('创作工作台')+`<div class="empty"><h3>暂无草稿</h3><br>${btn('新建草稿','generate')}</div>`;
  if(!edit||edit.id!==d.id){edit=structuredClone(d);selected=d.id;slide=0;}const issues=S.draftChecks[d.id]||[];
  return topHead('创作工作台',btn(icon('plus')+' 新建草稿','generate'))+`<div class="actions" style="margin-bottom:20px"><select id="draft-select" class="draft-select" aria-label="选择草稿">${scoped(S.drafts).map(x=>`<option value="${x.id}"${x.id===d.id?' selected':''}>${esc(x.title)} · ${esc(accountName(x.accountId))} · ${statusNames[x.status]}</option>`).join('')}</select><span class="badge neutral">${d.method==='ai'?'AI 生成':d.method==='template'?'本地事实模板':'编辑样例'}</span><span class="grow"></span>${btn('复制为新稿','duplicate','ghost',`data-id="${d.id}"`)}${btn('历史版本','history','ghost',`data-id="${d.id}"`)}</div><div class="studio-grid"><section class="editor"><form id="draft-form">${accountSelect('draft-account',edit.accountId)}${assetPicker(edit.productAssetIds||[],'draft')}${field('笔记标题','title',edit.title)}<div class="field-footer"><span></span><span id="title-count">${[...edit.title].length} / 20</span></div><div class="spacer"></div>${field('正文','body',edit.body,'textarea')}<div class="field-footer"><span></span><span id="body-count">${[...edit.body].length} / 1000</span></div><div class="spacer"></div><div class="form-grid">${field('话题标签 · 用逗号分隔','tags',edit.tags.join('，'))}<div class="field"><label for="series">内容栏目</label><select id="series" name="series">${['通信小麻烦','接通实验','一起打磨'].map(x=>`<option${edit.series===x?' selected':''}>${x}</option>`).join('')}</select></div></div><details class="slide-fields" open><summary>图集文案 · ${edit.slides.length} 页</summary>${edit.slides.map((p,i)=>`<div class="slide-field"><label for="slide-title-${i}">PAGE ${String(i+1).padStart(2,'0')} · ${i===0?'封面':'内页'}</label><input id="slide-title-${i}" data-slide="${i}" data-key="headline" aria-label="第${i+1}页标题" value="${esc(p.headline)}"><textarea data-slide="${i}" data-key="body" aria-label="第${i+1}页正文" rows="3">${esc(p.body)}</textarea><button type="button" class="btn ghost" data-action="remove-slide" data-index="${i}">移除此页</button></div>`).join('')}${btn('＋ 加一页','add-slide','light')}</details><div class="spacer"></div>${field('待补事实或素材 · 每行一项','gaps',edit.gaps.join('\n'),'textarea','补齐后可清除此项，保存草稿后重新检查。这里没有完整的自动事实审核。')}<div class="review-box ${issues.length?'issues':''}"><strong>${issues.length?'待处理':'自动基础检查通过'}</strong>${issues.length?`<ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>请人工复核事实、图片和当前产品阶段。</p>'}<p class="muted">${d.approved?'已标记人工审核通过':'尚未标记审核通过'} · 修改保存后需重新审核</p></div><div class="actions"><button class="btn" type="submit">保存草稿</button>${btn('核对通过','approve','light',`data-id="${d.id}"`)}${btn(icon('calendar')+' 安排发布','schedule','light',`data-id="${d.id}"`)}<span id="save-state" class="muted" style="font-size:11px">已保存 · v${d.revision}</span></div></form></section><aside class="preview-panel"><div class="preview-top"><span>图文预览 · 3:4</span><span id="page-indicator">${slide+1} / ${edit.slides.length}</span></div><img id="cover-preview" class="cover-preview" src="${coverURI(edit,slide)}" alt="原创图文预览"><div class="preview-pagination">${edit.slides.map((_,i)=>`<button data-action="slide" data-index="${i}" class="${i===slide?'active':''}" aria-label="预览第${i+1}页">${String(i+1).padStart(2,'0')}</button>`).join('')}</div><div class="actions">${btn(icon('download')+' 导出图文包','export','light')}${btn('下载当前页','download-slide','ghost')}</div><p class="preview-caption">1200 × 1600 PNG · 原创文字图解<br>画面为概念排版，不能代替实机照片或测试证据。</p><div class="panel"><span class="muted">参考说明</span><p class="preview-caption">${esc(d.adaptation||'直接根据产品资料组织内容。')}</p>${d.referenceIds.map(rid=>{const r=S.inspirations.find(x=>x.id===rid);return r?btn('↗ '+esc(r.title),'reference','ghost',`data-id="${rid}"`):'<small class="muted">原参考已删除</small>';}).join('')}</div></aside></div>`;}
function calendar(){const dailyAccounts=(accountFilter==='all'?activeAccounts():allAccounts().filter(a=>a.id===accountFilter));return topHead('发布排期',btn('每日任务设置','daily','light'))+`<div class="calendar-layout"><section><div class="daily-account-list">${dailyAccounts.map(a=>`<div class="panel daily-account-row"><div><strong>${esc(a.name)}</strong><span class="badge ${a.enabled&&!a.archived?'':'neutral'}">${a.archived?'已归档':a.enabled?'启用':'停用'}</span><p>${a.settings.enabled?'每日任务已开启':'每日任务未开启'} · ${esc(a.settings.time)} · ${esc(a.settings.timezone)} · ${a.settings.mode==='automatic'?'自动发布':'审核后发布'}</p></div>${!a.archived?btn('设置','daily','light',`data-id="${a.id}"`):''}</div>`).join('')||'<div class="empty">暂无账号</div>'}</div><div class="section-head"><h2>发布队列</h2><span class="muted" style="font-size:11px">按浏览器时区显示</span></div><div class="jobs">${scoped(S.jobs).slice().sort((a,b)=>b.scheduledAt.localeCompare(a.scheduledAt)).map(j=>{const dt=new Date(j.scheduledAt);return `<article class="job"><div class="job-date"><span>${dt.getMonth()+1} 月</span><b>${dt.getDate()}</b><span>${dt.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</span></div><div class="job-info"><div class="actions">${badge(j.status)}${accountTag(j.accountId,j.accountName)}</div><h3>${esc(j.title)}</h3><p>${esc(j.error||'')}</p>${j.noteUrl?`<a class="source-link" href="${esc(j.noteUrl)}" target="_blank" rel="noopener noreferrer">查看笔记 ↗</a>`:''}<div class="actions">${btn('查看草稿','edit','ghost',`data-id="${j.draftId}"`)}${['scheduled','blocked'].includes(j.status)?btn('取消排期','job-cancel','ghost',`data-id="${j.id}"`):''}${j.status==='blocked'&&j.attempts===0?btn('重新入队','job-retry','light',`data-id="${j.id}"`):''}${j.status==='uncertain'?btn('核对结果','job-verify','light',`data-id="${j.id}"`):''}</div></div></article>`;}).join('')||`<div class="empty"><h3>暂无发布任务</h3>${btn('去创作台','nav','light','data-page="studio"')}</div>`}</div></section><aside><div class="panel"><h3>接入状态</h3>${connectors()}<p class="preview-caption">服务运行时执行排期。结果不明时停止自动重试。</p>${btn('账号管理','nav','ghost','data-page="accounts"')}</div></aside></div>`;}
function accounts(){const items=allAccounts().filter(a=>accountView==='archived'?a.archived:!a.archived);return topHead('账号管理',btn(icon('plus')+' 添加账号','account-new'))+`<div class="filters"><button class="filter ${accountView==='active'?'active':''}" data-action="account-view" data-view="active">账号列表</button><button class="filter ${accountView==='archived'?'active':''}" data-action="account-view" data-view="archived">已归档</button><span class="shared-note">产品资料和灵感库共用</span></div><div class="account-list">${items.map(a=>{const drafts=S.drafts.filter(d=>d.accountId===a.id),jobs=S.jobs.filter(j=>j.accountId===a.id);return `<article class="account-card"><div class="account-card-head"><div class="account-avatar">${a.type==='official'?'官':'小'}</div><div class="account-main"><div class="account-name"><h2>${esc(a.name)}</h2><span class="badge neutral">${a.type==='official'?'官方账号':'普通账号'}</span>${a.id===S.defaultAccountId?'<span class="badge">默认</span>':''}</div><p>${esc(a.handle||'未填写小红书号')}${a.profileUrl?` · <a href="${esc(a.profileUrl)}" target="_blank" rel="noopener noreferrer">主页 ↗</a>`:''}</p></div><span class="badge ${a.archived||!a.enabled?'neutral':''}">${a.archived?'已归档':a.enabled?'启用':'停用'}</span></div><div class="account-details"><div><span>发布目标</span><strong>${a.bridgeAccountId?esc(a.bridgeAccountId):'未配置'}</strong><small>${accountReady(a.id)?'配置就绪，待实际核对':'发布器未接通'}</small></div><div><span>草稿</span><strong>${drafts.filter(d=>d.status==='draft').length}</strong></div><div><span>待发布</span><strong>${jobs.filter(j=>['scheduled','blocked','uncertain','publishing'].includes(j.status)).length}</strong></div><div><span>已发布</span><strong>${jobs.filter(j=>j.status==='published').length}</strong></div></div>${a.notes?`<p class="account-notes">${esc(a.notes)}</p>`:''}<div class="account-actions">${btn(a.archived?'查看':'编辑','account-edit','light',`data-id="${a.id}"`)}${!a.archived?`${btn('每日任务','daily','light',`data-id="${a.id}"`)}${btn(a.enabled?'停用':'启用','account-toggle','ghost',`data-id="${a.id}"`)}${a.id!==S.defaultAccountId?btn('设为默认','account-default','ghost',`data-id="${a.id}"`):''}<span class="grow"></span>${btn('归档','account-archive','ghost',`data-id="${a.id}"`)}`:''}</div></article>`;}).join('')||'<div class="empty">暂无账号</div>'}</div>`;}

const assetKindLabels={model:'3D 模型',icon:'图标',image:'产品图片',brochure:'宣传册'};
const renderLabels={queued:'排队中',running:'渲染中',completed:'已完成',failed:'失败'};
function productAssets(){return S.productAssets||[];}
function productAsset(id){return productAssets().find(a=>a.id===id);}
function selectableAssets(){return productAssets().filter(a=>['image','icon'].includes(a.kind));}
function assetBytes(value){const n=Number(value)||0;return n>=1024*1024?`${(n/1024/1024).toFixed(1)} MB`:n>=1024?`${(n/1024).toFixed(1)} KB`:`${n} B`;}
function latestRender(id){return (S.productRenders||[]).filter(j=>j.assetId===id).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)))[0];}
function assetFileUrl(a){return a.fileUrl||`/api/product-assets/${encodeURIComponent(a.id)}/file`;}
function assetPreviewUrl(a){const job=latestRender(a.id);return a.previewUrl||(job?.status==='completed'?job.previewUrl:'')||'';}
function assetTypeIcon(a){return icon(a.kind==='model'?'box':a.kind==='brochure'?'file':'image');}
function assetRenderControls(a){if(a.kind!=='model')return '';const job=latestRender(a.id),running=job&&['queued','running'].includes(job.status);return `<div class="asset-render"><select name="renderPreset" aria-label="${esc(a.name)}渲染视角"><option value="studio">标准视角</option><option value="front">正面</option><option value="angle">侧角</option></select>${btn(running?renderLabels[job.status]:'生成产品图','asset-render','light',`data-id="${a.id}"${!a.renderable||running?' disabled':''}`)}</div>${job?`<div class="asset-render-status ${job.status==='failed'?'is-error':''}"><span class="badge ${job.status==='failed'?'warn':['queued','running'].includes(job.status)?'neutral':''}">${renderLabels[job.status]||esc(job.status)}</span>${job.error?`<p>${esc(job.error)}</p>`:''}${job.status==='completed'&&job.imageAssetId?'<small>生成图已加入产品图片</small>':''}</div>`:a.renderStatus==='needs_setup'?'<p class="asset-render-hint">渲染环境待配置</p>':!a.renderable?'<p class="asset-render-hint">暂不支持此模型渲染</p>':''}`;}
function assetLibrary(){const items=productAssets().filter(a=>assetFilter==='all'||a.kind===assetFilter);return `<div class="filters asset-filters">${[['all','全部'],...Object.entries(assetKindLabels)].map(([key,label])=>`<button class="filter ${assetFilter===key?'active':''}" data-action="asset-filter" data-kind="${key}">${label}${key==='all'?'':` <span>${productAssets().filter(a=>a.kind===key).length}</span>`}</button>`).join('')}<span class="shared-note">${items.length} 项</span></div><div class="product-asset-grid">${items.map(a=>{const preview=assetPreviewUrl(a);return `<article class="asset-card"><button class="asset-preview" data-action="asset-preview" data-id="${a.id}" aria-label="预览 ${esc(a.name)}">${preview?`<img src="${esc(preview)}" alt="${esc(a.name)}预览" loading="lazy">`:`<span class="asset-placeholder">${assetTypeIcon(a)}<small>暂无预览</small></span>`}</button><div class="asset-card-body"><div class="asset-card-title"><h3>${esc(a.name||a.originalName)}</h3><span class="badge neutral">${assetKindLabels[a.kind]||esc(a.kind)}</span></div><p class="asset-file-meta">${esc(a.originalName||a.name)} · ${assetBytes(a.size)}</p>${a.description?`<p class="asset-description">${esc(a.description)}</p>`:''}${a.kind==='model'?`<p class="asset-storage-note">${a.storage==='linked'?'本地引用，不复制大文件':'本机模型文件'}</p>`:''}${assetRenderControls(a)}<div class="asset-card-actions">${btn('预览','asset-preview','ghost',`data-id="${a.id}"`)}<a class="btn ghost" href="${esc(assetFileUrl(a))}" download="${esc(a.originalName||a.name)}">下载原文件</a></div></div></article>`;}).join('')||'<div class="empty">暂无素材</div>'}</div>`;}
function product(){return topHead('产品资料',productTab==='assets'?btn(icon('plus')+' 上传素材','asset-upload'):'' )+`<div class="product-tabs"><button class="${productTab==='facts'?'active':''}" data-action="product-tab" data-tab="facts">产品资料</button><button class="${productTab==='assets'?'active':''}" data-action="product-tab" data-tab="assets">素材库 <span>${productAssets().length}</span></button></div>`+(productTab==='assets'?assetLibrary():productFacts());}
function assetPicker(selected=[],scope='draft'){const ids=Array.isArray(selected)?selected:[],items=selectableAssets();return `<details class="asset-picker"><summary>产品素材 <span>${ids.length?`已选 ${ids.length} 项`:'选填'}</span></summary>${items.length?`<div class="asset-pick-list">${items.map(a=>`<label class="asset-pick-row"><input type="checkbox" name="productAssetIds" value="${a.id}"${ids.includes(a.id)?' checked':''}>${assetPreviewUrl(a)?`<img src="${esc(assetPreviewUrl(a))}" alt="" loading="lazy">`:`<span class="asset-pick-placeholder">${assetTypeIcon(a)}</span>`}<span><strong>${esc(a.name||a.originalName)}</strong><small>${assetKindLabels[a.kind]} · ${assetBytes(a.size)}</small></span></label>`).join('')}</div>`:'<p class="asset-picker-note">素材库还没有可选图片或图标。</p>'}<p class="asset-picker-note">随草稿保存，导出包包含原文件；尚未自动合成到图集。</p></details>`;}
function assetPreviewModal(id){const a=productAsset(id);if(!a)return;const preview=assetPreviewUrl(a),dimensions=a.metadata?.width&&a.metadata?.height?`${a.metadata.width} × ${a.metadata.height}`:'';modal('素材预览','',`<div class="asset-modal"><div class="asset-modal-preview">${preview?`<img src="${esc(preview)}" alt="${esc(a.name)}预览">`:`<span class="asset-placeholder">${assetTypeIcon(a)}<small>暂无预览</small></span>`}</div><div class="asset-modal-info"><h3>${esc(a.name||a.originalName)}</h3><p>${esc(a.originalName||a.name)}</p><p>${assetKindLabels[a.kind]||esc(a.kind)} · ${assetBytes(a.size)}${dimensions?' · '+esc(dimensions):''}</p>${a.sourceLabel?`<p>${esc(a.sourceLabel)}</p>`:''}${a.description?`<p>${esc(a.description)}</p>`:''}${a.kind==='model'&&a.storage==='linked'?'<p>本地引用，不复制大文件</p>':''}</div>${assetRenderControls(a)}<div class="modal-actions"><a class="btn light" href="${esc(assetFileUrl(a))}" download="${esc(a.originalName||a.name)}">下载原文件</a></div></div>`);}
function assetUploadModal(){modal('上传素材','',`<form id="asset-upload-form"><div class="field"><label for="asset-upload-kind">素材类型</label><select id="asset-upload-kind" name="kind"><option value="image">产品图片</option><option value="icon">图标</option><option value="brochure">宣传册</option></select></div><div class="field"><label for="asset-upload-file">文件</label><input id="asset-upload-file" type="file" name="assetFile" accept="image/png,image/jpeg,image/webp,image/svg+xml,application/pdf" required><small>单文件最多 20 MB</small></div><div class="modal-actions"><button class="btn" type="submit">上传</button></div></form>`);}
function productFacts(){const p=S.product;return `<div class="product-banner"><h2>${esc(p.name)}</h2><p>${esc(p.summary)}</p></div><div class="product-grid"><section class="editor"><form id="product-form"><div class="form-grid">${field('产品名称','name',p.name)}${field('品牌 / 团队','brand',p.brand)}</div>${field('当前产品阶段','stage',p.stage)}${field('产品一句话说明','summary',p.summary,'textarea')}${field('资料记录的产品能力 · 每行一条','facts',p.facts.join('\n'),'textarea','功能方向来自文档；结果性描述仍需当前实机验证。')}${field('必须讲清的使用条件 · 每行一条','conditions',p.conditions.join('\n'),'textarea')}${field('尚无依据的承诺 · 每行一条','restrictions',p.restrictions.join('\n'),'textarea')}${field('资料来源 · 每行一个 https 链接','sources',p.sources.join('\n'),'textarea')}<div class="actions"><button class="btn" type="submit">保存产品资料</button><small class="muted">会使未发布草稿的审核状态失效</small></div></form></section><aside><div class="panel"><h3>资料来源</h3><p class="preview-caption">已整理此前读取的资料快照。这里保存链接与产品事实，目前不会自动拉取飞书的新内容。</p>${p.sources.map((src,i)=>`<a class="source-link" href="${esc(src)}" target="_blank" rel="noopener noreferrer">${i===0?'产品说明与内测边界':'项目资料 '+(i+1)} ↗<small>${esc(new URL(src).hostname)}</small></a>`).join('')}<div class="note-box">资料更新后，请把最新能力和限制补进左侧；生成时会记录本次资料版本。</div><p class="preview-caption">最近保存：${date(p.updatedAt)}</p></div></aside></div>`;}
function settings(){return topHead('设置')+`<div class="settings-grid"><section class="panel"><h2>服务接入</h2>${connectors()}<div class="note-box">当前为本机单人工作台，只监听 127.0.0.1。运行数据保存在 runtime/。部署给多人使用前还需身份验证与独立存储。</div></section><section class="panel"><h2>AI 截图分析与创作</h2><ol class="setting-steps"><li>在项目目录复制 <code>.env.example</code> 为 <code>.env</code>。</li><li>填写 <code>REDPILOT_AI_KEY</code>、<code>REDPILOT_AI_MODEL</code>。</li><li>使用兼容服务时修改 <code>REDPILOT_AI_BASE_URL</code>。</li><li>重启本地服务。需支持图片输入与 JSON 模式。</li></ol><p class="preview-caption">启用后，点击分析或 AI 生成会向所配置服务发送对应截图、参考文字和产品资料。未配置时可用本地事实模板，页面会标明生成方式。</p></section><section class="panel"><h2>小红书发布器</h2><p class="preview-caption">当前没有内置小红书登录或发布驱动。可连接实现了本项目协议的发布桥，负责图集渲染、账号登录、实际发布与结果核对。</p><ol class="setting-steps"><li>填写 <code>REDPILOT_PUBLISH_URL</code>。</li><li>填写发布桥令牌 <code>REDPILOT_PUBLISH_TOKEN</code>。</li><li>在账号管理中填写各账号的发布目标 ID。</li><li>具体请求和幂等要求见仓库 <code>docs/publishing-bridge.md</code>。</li></ol><div class="note-box">仅填写配置不代表已连通。收到经核对的真实笔记链接后，任务才显示已发布。</div></section><section class="panel"><h2>数据备份</h2><p class="preview-caption">数据存储在本机，不会随代码上传。可下载资料、收藏索引、草稿和任务的 JSON 快照；图片文件需另外备份 runtime/uploads。</p>${btn(icon('download')+' 导出数据快照','backup','light')}<div class="spacer"></div><h3>运行记录</h3>${S.events.slice(0,5).map(e=>`<div class="event">${esc(e.message)}<time>${date(e.at)}</time></div>`).join('')||'<p class="preview-caption">还没有运行记录。</p>'}</section></div>`;}
function render(){if(!S)return;page=labels[page]?page:'overview';$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-symbol">↗</div><div><div class="brand-name">RedPilot<span class="brand-cn">薯航</span></div></div></div><nav class="nav" aria-label="工作台导航">${Object.entries(labels).map(([key,label],i)=>`<button class="${page===key?'active':''}" data-action="nav" data-page="${key}"${page===key?' aria-current="page"':''}>${icon(['grid','library','pen','calendar','users','box','settings'][i])}${label}${key==='library'?`<span class="count">${String(S.inspirations.length).padStart(2,'0')}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-card"><strong><span class="dot"></span>${esc(S.product.name)} 工作台</strong><p>产品宣传<br>${esc(S.product.brand)}</p></div><div class="local-label">${icon('box').replace('<svg ','<svg width="13" height="13" ')} 本机存储</div></div></aside><main class="main"><div class="content">${({overview,library,studio,calendar,accounts,product,settings}[page])()}</div></main></div>`;}
function modal(title,subtitle,body){$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="关闭弹窗">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
let uploadFiles=[];
function upload(target){uploadFiles=[];modal(target?'补充资料':'收藏灵感','同一篇笔记的多张截图会保存为一组。链接暂只保存来源，不自动抓取网页。',`<form id="upload-form" data-target="${target||''}">${field('收藏标题（选填）','ref-title','')}${field('笔记或账号链接（选填）','ref-url','','url')}<div class="field"><span>截图（选填）</span><label class="dropzone" id="dropzone">＋ 选择图片，或拖到这里<input id="upload-input" type="file" accept="image/png,image/jpeg,image/webp" multiple aria-label="选择参考截图"><small>每组最多 6 张 · 单张 8MB · 总计 16MB</small></label><div id="file-list" class="file-list"></div></div>${field('可见正文（选填）','ref-text','','textarea','链接无法读取时，可直接粘贴你看到的正文。')}${field('喜欢哪里 / 想学什么（选填）','ref-note','','textarea')}${field('标签 · 用逗号分隔（选填）','ref-tags','')}<div class="modal-actions"><button class="btn" type="submit">保存收藏</button></div></form>`);}
function formatAnalysis(value){if(Array.isArray(value))return `<ul>${value.map(x=>`<li>${typeof x==='object'?formatAnalysis(x):esc(x)}</li>`).join('')}</ul>`;if(value&&typeof value==='object')return Object.entries(value).map(([k,v])=>`<strong>${esc(analysisLabels[k]||k)}</strong>${formatAnalysis(v)}`).join('<br>');return `<p>${esc(value)}</p>`;}
const analysisLabels={topic:'选题角度',titlePattern:'标题结构',visual:'封面视觉',structure:'内容结构',adaptation:'产品适配',observations:'可见观察',inferences:'推断',unknown:'缺失信息',positioning:'账号定位',visible_cover_patterns:'可见封面规律',unknown_from_screenshot:'截图无法确定的内容',topic_angle:'选题角度',do_not_transfer:'不能沿用的结论'};
function reference(rid){const r=S.inspirations.find(x=>x.id===rid);if(!r)return;modal('收藏详情',r.scope||'只分析已提供的截图与文字，不推测未读取内容。',`<div class="detail-grid"><div class="detail-images">${r.assets.map((src,i)=>`<a href="${esc(src)}" target="_blank" rel="noopener"><img src="${esc(src)}" alt="参考截图 ${i+1}"></a>`).join('')||'<div class="empty">暂无截图</div>'}</div><div><form id="reference-form" data-id="${rid}">${field('收藏标题','detail-title',r.title)}${field('标签 · 用逗号分隔','detail-tags',r.tags.join('，'))}<label class="check-label"><input type="checkbox" name="pool"${r.pool?' checked':''}>加入每日选题池</label><div class="actions" style="margin-top:15px"><button class="btn light" type="submit">保存修改</button>${btn('补充截图 / 正文','upload','ghost',`data-id="${rid}"`)}</div></form>${r.url?`<a class="source-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">查看原始链接 ↗</a>`:''}<p class="preview-caption">${r.method==='editorial_seed'?'以下为此前人工浏览整理的分析样例。':r.method==='ai'?'以下由已配置模型分析，仅基于提供的资料。':'尚未执行 AI 分析。'}<br>${r.note?'备注：'+esc(r.note):''}</p>${r.text?`<details class="analysis-block"><summary>已保存的参考正文</summary><p>${esc(r.text)}</p></details>`:''}${r.analysis?Object.entries(r.analysis).map(([k,v])=>`<section class="analysis-block"><h3>${esc(analysisLabels[k]||k)}</h3>${formatAnalysis(v)}</section>`).join(''):'<div class="note-box">补充截图或正文后可调用 AI 分析。只有链接时，不会假装已经读过内容。</div>'}</div></div><div class="modal-actions">${btn('删除收藏','delete-ref','danger',`data-id="${rid}"`)}<span class="grow"></span>${btn(icon('spark')+' 分析参考','analyze','light',`data-id="${rid}"`)}${btn('参考创作','generate','',`data-id="${rid}"`)}</div>`);}
function accountModal(id){const a=accountById(id),readonly=Boolean(a?.archived);modal(readonly?'账号详情':a?'编辑账号':'添加账号','',`<form id="account-form" data-id="${a?.id||''}"><fieldset${readonly?' disabled':''}><div class="form-grid">${field('账号名称','account-name',a?.name||'')}<div class="field"><label for="account-type">类型</label><select id="account-type" name="type"><option value="official"${a?.type==='official'?' selected':''}>官方账号</option><option value="personal"${!a||a.type==='personal'?' selected':''}>普通账号</option></select></div></div><div class="form-grid">${field('小红书号（选填）','account-handle',a?.handle||'')}${field('主页链接（选填）','account-profile',a?.profileUrl||'','url')}</div>${field('发布目标 ID（选填）','account-bridge',a?.bridgeAccountId||'','text','与发布器中的账号 ID 对应，填写后仍需在发布器完成登录。')}${field('备注（选填）','account-notes',a?.notes||'','textarea')}<label class="check-label"><input name="enabled" type="checkbox"${!a||a.enabled?' checked':''}>启用账号</label></fieldset>${readonly?'<div class="note-box">已归档，保留历史记录。</div>':'<div class="modal-actions"><button class="btn" type="submit">保存账号</button></div>'}</form>`);}
function generateModal(rid){if(dirty){toast('请先保存当前草稿');return;}if(!activeAccounts().length){toast('请先添加账号');return;}modal('新建草稿','从产品事实出发，借鉴参考的结构与表达。',`<form id="generate-form">${accountSelect('gen-account',chosenAccount()?.archived?S.defaultAccountId:chosenAccount()?.id||S.defaultAccountId)}${assetPicker([],'generate')}<div class="field"><label for="gen-ref">参考灵感</label><select name="referenceId" id="gen-ref"><option value="">不选参考 · 从产品资料开始</option>${S.inspirations.map(r=>`<option value="${r.id}"${r.id===rid?' selected':''}>${esc(r.title)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="gen-mode">借鉴方式</label><select name="mode" id="gen-mode"><option>综合借鉴</option><option>学习封面排版</option><option>学习文案结构</option></select></div><div class="field"><label for="gen-method">创作方式</label><select name="method" id="gen-method"><option value="${S.capabilities.ai?'ai':'template'}">${S.capabilities.ai?'AI 分析与创作':'本地事实模板（未启用 AI）'}</option>${S.capabilities.ai?'<option value="template">本地事实模板</option>':''}</select></div></div>${field('这篇想讲什么（选填）','instruction','','textarea','例如：学习这个问题式封面，讲备用机里真正需要留下的功能。')}<div class="note-box">${S.capabilities.ai?'AI 会收到所选截图、参考分析和产品资料。生成结果需要核对事实和素材。':'本地模板按已保存的产品事实排版，不执行截图识别、自由改写或参考风格迁移。你的创作要求会保留在草稿中。'}</div><div class="modal-actions"><button class="btn" type="submit">${icon('spark')} 创建草稿</button></div></form>`);}
function daily(accountId){const a=accountById(accountId)||chosenAccount();if(!a)return toast('请先添加账号');if(a.archived)return toast('账号已归档');const settings=a.settings;modal('每日任务','',`<form id="settings-form" data-id="${a.id}">${accountSelect('daily-account',a.id)}<label class="check-label"><input name="enabled" type="checkbox"${settings.enabled?' checked':''}>启用每日任务</label><div class="spacer"></div><div class="form-grid">${field('执行时间','time',settings.time,'time')}${field('时区','timezone',settings.timezone,'text','例如 Asia/Shanghai')}</div><div class="field"><label for="daily-mode">发布模式</label><select name="mode" id="daily-mode"><option value="automatic"${settings.mode==='automatic'?' selected':''}>自动生成并发布</option><option value="review"${settings.mode==='review'?' selected':''}>审核后发布</option></select></div><div class="note-box">${!a.enabled?'账号已停用，每日任务暂停执行。<br>':''}仅在本地服务运行时执行，每天一次。AI 或发布器未配置时记录原因。</div><div class="modal-actions"><button class="btn" type="submit">保存设置</button></div></form>`);}

function schedule(did){const d=S.drafts.find(x=>x.id===did);if(dirty){toast('请先保存草稿并核对通过');return;}const a=accountById(d.accountId);const next=new Date(Date.now()+3600000);const local=new Date(next-next.getTimezoneOffset()*60000).toISOString().slice(0,16);modal('安排发布','',`<form id="schedule-form" data-id="${did}" data-account="${esc(d.accountId)}"><div class="schedule-target"><span>目标账号</span><strong>${esc(a?.name||'未分配账号')}</strong><small>${esc(d.title)}</small></div>${field('发布时间 · 按浏览器时区','scheduledAt',local,'datetime-local')}<div class="note-box">${!a?.enabled||a?.archived?'账号已停用或归档，请先调整草稿归属。':!d.approved?'请先在创作台核对图文。':!accountReady(d.accountId)?'该账号发布器未接通。可先保存排期，到时会标记待处理。':'发布前会重新检查资料版本。'}</div><div class="modal-actions"><button class="btn" type="submit"${!a?.enabled||a?.archived?' disabled':''}>确认排期</button></div></form>`);}

function updatePreview(){if(!edit)return;$('#cover-preview').src=coverURI(edit,slide);$('#page-indicator').textContent=`${slide+1} / ${edit.slides.length}`;$('#title-count').textContent=`${[...edit.title].length} / 20`;$('#body-count').textContent=`${[...edit.body].length} / 1000`;$('#save-state').textContent=dirty?'有修改，待保存':'已保存';}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function png(d,index){const image=new Image();image.src=coverURI(d,index);await image.decode();const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1600;canvas.getContext('2d').drawImage(image,0,0);return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('图片导出失败')),'image/png'));}
function crc32(buf){let crc=-1;for(const n of buf){crc^=n;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^-1)>>>0;}
function zip(files){const parts=[],central=[],encoder=new TextEncoder();let offset=0;for(const [name,data] of files){const nameBytes=encoder.encode(name),checksum=crc32(data),header=new Uint8Array(30+nameBytes.length),v=new DataView(header.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,checksum,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,nameBytes.length,true);header.set(nameBytes,30);parts.push(header,data);const c=new Uint8Array(46+nameBytes.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,checksum,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,nameBytes.length,true);cv.setUint32(42,offset,true);c.set(nameBytes,46);central.push(c);offset+=header.length+data.length;}const centralSize=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
function safeAssetFilename(name){return String(name||'asset').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').replace(/^\.+/,'').slice(0,180)||'asset';}
async function exportPack(){const d=edit;if(!d)return;toast('正在打包图集…');const encoder=new TextEncoder(),ids=[...new Set(d.productAssetIds||[])],assets=ids.map(id=>productAsset(id));if(assets.some(a=>!a||!['image','icon'].includes(a.kind)))throw Error('部分素材已不可用，请重新选择');const files=[['post.txt',encoder.encode(`${d.title}\n\n${d.body}\n\n${d.tags.map(t=>'#'+t).join(' ')}\n\n生成方式：${d.method}\n本图集为原创文字示意，请在发布前核对。${assets.length?'\n产品素材原文件保存在 sources/，未合成进图集。':''}`)]];for(let i=0;i<d.slides.length;i++)files.push([`${String(i+1).padStart(2,'0')}.png`,new Uint8Array(await (await png(d,i)).arrayBuffer())]);if(assets.length){files.push(['sources/README.txt',encoder.encode('此目录保存本篇选择的原始产品素材，未合成进导出的文字图集。\n')]);for(let i=0;i<assets.length;i++){const asset=assets[i],response=await fetch(assetFileUrl(asset));if(!response.ok)throw Error(`素材「${asset.name}」下载失败，未导出图文包`);files.push([`sources/${String(i+1).padStart(2,'0')}-${safeAssetFilename(asset.originalName||asset.name)}`,new Uint8Array(await response.arrayBuffer())]);}}download(zip(files),'RedPilot-'+d.title.replace(/[/\\:*?"<>|]/g,'')+'.zip');toast(assets.length?'已导出图文与原始素材':'已导出文案与全部 PNG 图片');}
function split(value){return String(value||'').split(/[，,\n]/).map(x=>x.trim()).filter(Boolean);}
function splitLines(value){return String(value||'').split('\n').map(x=>x.trim()).filter(Boolean);}
function addFiles(files){const next=[...uploadFiles,...files];if(next.length>6)return toast('每组最多 6 张截图');if(next.some(f=>f.size>8*1024*1024)||next.reduce((n,f)=>n+f.size,0)>16*1024*1024)return toast('单张最多 8MB，总计最多 16MB');if(next.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type)))return toast('仅支持 PNG、JPEG、WebP');uploadFiles=next;$('#file-list').textContent=next.map(f=>f.name).join(' · ');}
const fileData=f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,data:reader.result.split(',')[1]});reader.onerror=()=>reject(Error('无法读取图片'));reader.readAsDataURL(f);});
async function action(el){const a=el.dataset.action,key=el.dataset.id;if(a==='close'){if(!busy)$('#modal').close();return;}if(a==='nav')return nav(el.dataset.page);if(a==='upload')return upload(key);if(a==='reference')return reference(key);if(a==='generate')return generateModal(key);if(a==='daily')return daily(key);if(a==='product-tab'){productTab=el.dataset.tab;render();return;}if(a==='asset-filter'){assetFilter=el.dataset.kind;render();return;}if(a==='asset-preview')return assetPreviewModal(key);if(a==='asset-upload')return assetUploadModal();if(a==='account-new')return accountModal();if(a==='account-edit')return accountModal(key);if(a==='account-view'){accountView=el.dataset.view;render();return;}if(a==='schedule')return schedule(key);if(a==='edit'){selected=key;const d=S.drafts.find(x=>x.id===key);if(d&&accountFilter!=='all'&&d.accountId!==accountFilter)accountFilter=d.accountId;return nav('studio');}if(a==='filter'){filter=el.dataset.filter;render();return;}if(a==='slide'){slide=Number(el.dataset.index);updatePreview();$('.preview-pagination').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===slide));return;}
if(a==='add-slide'||a==='remove-slide'){if(a==='add-slide'){if(edit.slides.length>=9)return toast('最多 9 页');edit.slides.push({headline:'新的一页',body:''});}else{if(edit.slides.length===1)return toast('至少保留一页');edit.slides.splice(Number(el.dataset.index),1);}dirty=true;slide=Math.min(slide,edit.slides.length-1);render();updatePreview();return;}
if(a==='history'){const d=S.drafts.find(x=>x.id===key);return modal('历史版本','保留最近 20 次保存前的内容版本。',d.history.map(h=>`<details class="history-item"><summary>${date(h.at)} · ${esc(h.title)}</summary><p>${esc(h.body)}</p>${btn('复制该版文案','copy-history','light',`data-index="${d.history.indexOf(h)}"`)}</details>`).join('')||'<div class="empty">还没有历史版本。保存修改后会在这里出现。</div>');}
if(a==='copy-history'){const h=draftCurrent().history[Number(el.dataset.index)];await navigator.clipboard.writeText(h.title+'\n\n'+h.body);toast('已复制历史文案');return;}
if(a==='backup'){const {capabilities,draftChecks,...data}=S;download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'redpilot-backup.json');return;}
if(busy)return;busy=true;el.disabled=true;try{if(a==='analyze'){toast('正在分析提供的截图与文字…');await api(`inspirations/${key}/analyze`,{});await refresh(false);reference(key);toast('分析已保存');}
else if(a==='asset-render'){const preset=el.closest('.asset-card,.asset-modal').querySelector('select[name=renderPreset]').value;await api(`product-assets/${key}/render`,{preset});if($('#modal').open)$('#modal').close();productTab='assets';await refresh();toast('已加入渲染队列');}
else if(a==='approve'){if(dirty)throw Error('请先保存草稿，再标记核对通过');await api(`drafts/${key}/approve`,{});edit=null;await refresh();toast('已标记核对通过');}
else if(a==='duplicate'){const d=await api(`drafts/${key}/duplicate`,{accountId:accountById(draftCurrent()?.accountId)?.archived?S.defaultAccountId:draftCurrent()?.accountId});selected=d.id;edit=null;dirty=false;if(accountFilter!=='all')accountFilter=d.accountId;await refresh();toast('已复制为新草稿');}
else if(a==='account-toggle'){const account=accountById(key);await api(`accounts/${key}`,{enabled:!account.enabled},'PUT');await refresh();toast(account.enabled?'账号已停用':'账号已启用');}
else if(a==='account-default'){await api(`accounts/${key}/default`,{});await refresh();toast('已设为默认账号');}
else if(a==='account-archive'){if(!confirm('归档这个账号？历史草稿和发布记录会保留。'))return;await api(`accounts/${key}/archive`,{});if(accountFilter===key)accountFilter='all';await refresh();toast('账号已归档');}
else if(a==='delete-ref'){if(!confirm('删除这份收藏？已生成的草稿会保留。'))return;await api(`inspirations/${key}`,{},'DELETE');$('#modal').close();await refresh();toast('收藏已删除');}
else if(a.startsWith('job-')){await api(`jobs/${key}/${a.slice(4)}`,{});await refresh();toast('任务状态已更新');}
else if(a==='download-slide'){download(await png(edit,slide),`redpilot-${slide+1}.png`);}
else if(a==='export')await exportPack();}catch(e){toast(e.message);}finally{busy=false;el.disabled=false;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el);}});
document.addEventListener('input',e=>{const t=e.target;if(t.name==='productAssetIds'){const picker=t.closest('.asset-picker');picker.querySelector('summary span').textContent=`已选 ${picker.querySelectorAll('input:checked').length} 项`;}if(t.id==='library-search'){query=t.value;const start=t.selectionStart;render();$('#library-search').focus();try{$('#library-search').setSelectionRange(start,start);}catch{}return;}if(t.closest('#draft-form')){if(t.dataset.slide!==undefined)edit.slides[Number(t.dataset.slide)][t.dataset.key]=t.value;else if(t.name==='tags')edit.tags=split(t.value);else if(t.name==='gaps')edit.gaps=splitLines(t.value);else if(t.name==='accountId')edit.accountId=t.value;else if(t.name==='productAssetIds')edit.productAssetIds=[...t.closest('form').querySelectorAll('input[name=productAssetIds]:checked')].map(el=>el.value);else if(['title','body','series'].includes(t.name))edit[t.name]=t.value;dirty=true;updatePreview();}});
document.addEventListener('change',e=>{if(e.target.id==='account-filter'){if(dirty&&!confirm('放弃未保存的修改？')){e.target.value=accountFilter;return;}accountFilter=e.target.value;selected=null;edit=null;dirty=false;slide=0;render();return;}if(e.target.id==='daily-account'){daily(e.target.value);return;}if(e.target.id==='upload-input')addFiles(e.target.files);if(e.target.id==='draft-select'){if(dirty&&!confirm('放弃未保存的修改？')){e.target.value=selected;return;}selected=e.target.value;edit=null;dirty=false;slide=0;render();}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.add('dragging');}});
document.addEventListener('dragleave',e=>{if(e.target.closest('#dropzone'))$('#dropzone').classList.remove('dragging');});
document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.remove('dragging');addFiles(e.dataTransfer.files);}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=e.target,fd=new FormData(f),values=Object.fromEntries(fd),submit=f.querySelector('button[type=submit]');busy=true;if(submit)submit.disabled=true;try{if(f.id==='upload-form'){const result=await api('inspirations',{title:values['ref-title']||uploadFiles[0]?.name||'链接灵感',url:values['ref-url'],text:values['ref-text'],note:values['ref-note'],tags:split(values['ref-tags']),targetId:f.dataset.target||undefined,files:await Promise.all(uploadFiles.map(fileData))});$('#modal').close();await refresh();toast(result.merged?'已合并到现有收藏':'灵感已保存');}
else if(f.id==='asset-upload-form'){const file=f.querySelector('input[type=file]').files[0];if(!file)throw Error('请选择文件');if(file.size>20*1024*1024)throw Error('单文件最多 20 MB');await api('product-assets/upload',{...(await fileData(file)),kind:values.kind});$('#modal').close();productTab='assets';await refresh();toast('素材已上传');}
else if(f.id==='reference-form'){await api('inspirations/'+f.dataset.id,{title:values['detail-title'],tags:split(values['detail-tags']),pool:fd.has('pool')},'PUT');await refresh(false);reference(f.dataset.id);toast('收藏已更新');}
else if(f.id==='generate-form'){toast('正在创建草稿…');const d=await api('drafts',{...values,productAssetIds:fd.getAll('productAssetIds')});if(accountFilter!=='all')accountFilter=d.accountId;selected=d.id;edit=null;dirty=false;$('#modal').close();await refresh(false);nav('studio');toast(d.method==='ai'?'AI 草稿已保存，请核对图文':'本地事实模板已创建');}
else if(f.id==='draft-form'){await api('drafts/'+edit.id,edit,'PUT');if(accountFilter!=='all')accountFilter=edit.accountId;dirty=false;edit=null;await refresh();toast('草稿已保存');}
else if(f.id==='account-form'){const data={name:values['account-name'],type:values.type,handle:values['account-handle'],profileUrl:values['account-profile'],bridgeAccountId:values['account-bridge'],notes:values['account-notes'],enabled:fd.has('enabled')};await api(f.dataset.id?'accounts/'+f.dataset.id:'accounts',data,f.dataset.id?'PUT':'POST');$('#modal').close();await refresh();toast('账号已保存');}
else if(f.id==='product-form'){await api('product',{...values,facts:splitLines(values.facts),conditions:splitLines(values.conditions),restrictions:splitLines(values.restrictions),sources:splitLines(values.sources)},'PUT');await refresh();toast('产品资料已更新，旧稿需要重新核对');}
else if(f.id==='settings-form'){await api(`accounts/${f.dataset.id}/settings`,{...values,enabled:fd.has('enabled')},'PUT');$('#modal').close();await refresh();toast('每日设置已保存');}
else if(f.id==='schedule-form'){await api('drafts/'+f.dataset.id+'/schedule',{scheduledAt:new Date(values.scheduledAt).toISOString(),accountId:f.dataset.account});$('#modal').close();await refresh(false);nav('calendar');toast('排期已保存');}}catch(err){toast(err.message);}finally{busy=false;if(submit)submit.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
